import numpy as np

def check_basis(B):
    n = B.shape[0]
    if B.shape != (n, n) or np.linalg.matrix_rank(B) < n:
        raise ValueError('not a basis')

def coords(v, B):
    B = np.array(B, dtype=float)
    check_basis(B)
    c = np.linalg.solve(B, np.array(v, dtype=float))
    return (np.round(c, 6) + 0.0).tolist()

def matrix_in_basis(A, B):
    A = np.array(A, dtype=float)
    B = np.array(B, dtype=float)
    check_basis(B)
    M = np.linalg.solve(B, A @ B)
    return (np.round(M, 6) + 0.0).tolist()
